/* One OnePage signup, one delivery to each tool (round 41, run after `315`): new `onepage_integration_sends`, one row per connected tool (`integration_id`, deleted with it) and signup (`send_key`, a SHA-256 of the address, the form and the block, so it holds no address), written by the server just before a signup is sent (lib/onepage/integrations/deliver-server) and removed again when the send did not go. The same person signing up on the same block again is then not a second Zapier run, a second Make scenario or a second Google Sheets row. Row level security on, nothing granted to anon or authenticated; only the service role reads or writes it. New table only; no existing row changes. Until it runs, every signup is sent as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 324: run part 315 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_integration_sends (integration_id uuid NOT NULL REFERENCES public.onepage_integrations(id) ON DELETE CASCADE, send_key text NOT NULL CHECK (send_key ~ '^[0-9a-f]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (integration_id, send_key)); ALTER TABLE public.onepage_integration_sends ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_integration_sends FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, DELETE ON public.onepage_integration_sends TO service_role; END $do$;
notify pgrst, 'reload schema';
